SELECT analytics_order_facts.category, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year = 2025 AND analytics_order_facts.month = 9 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'retail' AND analytics_order_facts.customer_segment = 'small_business' AND analytics_order_facts.category = 'category_08' GROUP BY analytics_order_facts.category ORDER BY contribution_margin DESC, analytics_order_facts.category ASC LIMIT 10
